// Build Vapi response - final. Handles check_availability via Check Calendar overlap, and book_appointment via Create Booking result. Returns {results:[{toolCallId, result:"<JSON string>"}]}.
const validateItems = $('Validate booking').all().map(i => i.json);
let calendarItems = [];
try { calendarItems = $('Check Calendar').all().map(i => i.json); } catch (e) { calendarItems = []; }
const hasConflict = calendarItems.some(ev => ev && (ev.id || ev.summary || ev.start || ev.htmlLink));
let created = null;
try { const c = $('Create an event').first().json; if (c && (c.id || c.iCalUID)) created = c; } catch (e) { try { const c2 = $('Create Booking').first().json; if (c2 && (c2.id || c2.iCalUID)) created = c2; } catch (e2) { created = null; } }
const results = [];
for (const v of validateItems) {
  const fail = (msg) => (v.fnName === "book_appointment"
    ? { toolCallId: v.toolCallId, result: JSON.stringify({ booked: false, reason: "invalid_request", message: msg }) }
    : { toolCallId: v.toolCallId, result: JSON.stringify({ available: false, reason: "invalid_request", message: msg }) });
  if (!v.valid) { results.push(fail(v.errorMessage || "Invalid request.")); continue; }
  if (v.fnName === "check_availability") {
    if (hasConflict) { results.push({ toolCallId: v.toolCallId, result: JSON.stringify({ available: false, reason: "slot_unavailable", alternatives: [v.endDateTime] }) }); }
    else { results.push({ toolCallId: v.toolCallId, result: JSON.stringify({ available: true, service: v.service, startDateTime: v.startDateTime, endDateTime: v.endDateTime, timeZone: v.timeZone }) }); }
    continue;
  }
  if (v.fnName === "book_appointment") {
    if (hasConflict) { results.push({ toolCallId: v.toolCallId, result: JSON.stringify({ booked: false, reason: "slot_unavailable", message: "Requested time is no longer available." }) }); continue; }
    if (created && (created.id || created.iCalUID)) {
      results.push({ toolCallId: v.toolCallId, result: JSON.stringify({ booked: true, bookingReference: created.id || created.iCalUID, service: v.service, startDateTime: v.startDateTime, endDateTime: v.endDateTime, timeZone: v.timeZone }) });
    } else {
      results.push({ toolCallId: v.toolCallId, error: "Calendar booking is temporarily unavailable." });
    }
    continue;
  }
  results.push({ toolCallId: v.toolCallId, error: "Calendar booking is temporarily unavailable." });
}
if (results.length === 0) return [{ json: { results: [{ toolCallId: "unknown", error: "Calendar booking is temporarily unavailable." }] } }];
return [{ json: { results } }];
